1	/**
2	 * OAuth 2.0 Authorization Endpoint
3	 * GET /oauth/authorize
4	 * 
5	 * ユーザーに認可画面を表示し、同意を求める
6	 */
7	
8	import { createClient } from '@/lib/supabase/server';
9	import { NextResponse } from 'next/server';
10	import { NextRequest } from 'next/server';
11	import { isValidRedirectUri, createOAuthError } from '@/lib/oauth';
12	
13	export async function GET(request: NextRequest) {
14	  const { searchParams } = new URL(request.url);
15	  
16	  // OAuth パラメータを取得
17	  const clientId = searchParams.get('client_id');
18	  const redirectUri = searchParams.get('redirect_uri');
19	  const state = searchParams.get('state');
20	  const codeChallenge = searchParams.get('code_challenge');
21	  const codeChallengeMethod = searchParams.get('code_challenge_method');
22	  const responseType = searchParams.get('response_type');
23	  const scope = searchParams.get('scope') || 'openid profile';
24	
25	  // 必須パラメータのバリデーション
26	  if (!clientId || !redirectUri || !codeChallenge || !state) {
27	    return new Response(
28	      JSON.stringify(createOAuthError('invalid_request', 'Missing required parameters')),
29	      { status: 400, headers: { 'Content-Type': 'application/json' } }
30	    );
31	  }
32	
33	  if (responseType !== 'code') {
34	    return new Response(
35	      JSON.stringify(createOAuthError('unsupported_response_type', 'Only "code" is supported')),
36	      { status: 400, headers: { 'Content-Type': 'application/json' } }
37	    );
38	  }
39	
40	  if (codeChallengeMethod !== 'S256') {
41	    return new Response(
42	      JSON.stringify(createOAuthError('invalid_request', 'Only S256 code_challenge_method is supported')),
43	      { status: 400, headers: { 'Content-Type': 'application/json' } }
44	    );
45	  }
46	
47	  const supabase = await createClient();
48	
49	  // ユーザーのログイン状態を確認
50	  const { data: { user }, error: authError } = await supabase.auth.getUser();
51	
52	  console.log('[OAuth Authorize] getUser:', {
53	    hasUser: !!user,
54	    userId: user?.id,
55	    error: authError?.message,
56	    cookieNames: request.cookies.getAll().map(c => c.name).join(','),
57	  });
58	
59	  if (authError || !user) {
60	    // 未ログインの場合：ログイン画面へリダイレクト
61	    // リダイレクト先をパス+クエリで保存（内部URLの漏洩を防止）
62	    const requestUrl = new URL(request.url);
63	    const oauthPath = `${requestUrl.pathname}${requestUrl.search}`;
64	
65	    const loginUrl = new URL('/login', request.url);
66	    loginUrl.searchParams.set('redirect', request.url);
67	    const response = NextResponse.redirect(loginUrl, { status: 307 });
68	    // httpOnly Cookie にパスを保存（auth callback で読み取り）
69	    response.cookies.set('oauth_redirect', oauthPath, {
70	      httpOnly: true,
71	      secure: request.url.startsWith('https'),
72	      sameSite: 'lax',
73	      maxAge: 600,
74	      path: '/',
75	    });
76	    console.log('[OAuth Authorize] Redirecting to login, oauth_redirect cookie:', oauthPath.substring(0, 80));
77	    return response;
78	  }
79	
80	  // クライアントアプリケーションを検証（RPC経由）
81	  const { data: applications, error: appError } = await supabase
82	    .rpc('get_application_by_client_id', { p_client_id: clientId });
83	
84	  const application = applications?.[0];
85	
86	  if (appError || !application) {
87	    return new Response(
88	      JSON.stringify(createOAuthError('invalid_client', 'Unknown client_id')),
89	      { status: 400, headers: { 'Content-Type': 'application/json' } }
90	    );
91	  }
92	
93	  // リダイレクトURIを検証
94	  if (!isValidRedirectUri(redirectUri, application.redirect_uris)) {
95	    return new Response(
96	      JSON.stringify(createOAuthError('invalid_request', 'Invalid redirect_uri')),
97	      { status: 400, headers: { 'Content-Type': 'application/json' } }
98	    );
99	  }
100	
101	  // 既に承認済みかチェック（RPC経由）
102	  const { data: hasConsent } = await supabase
103	    .rpc('check_user_consent', { p_user_id: user.id, p_application_id: application.id });
104	
105	  const existingConsent = hasConsent;
106	
107	  // 承認画面にパラメータを渡す
108	  const consentUrl = new URL('/oauth/authorize/consent', request.url);
